{"content": "#!/usr/bin/env python3
"""Boundary / degenerate-case checks + direct check of derivation steps 1-4
of (FR) against the raw MISSION-section-2 recurrence.

Run from working dir root: python3 scratch/referee_edges.py
"""
import subprocess, math

RMAX = 700
QMAX = 1600

out = subprocess.run(["./solver", "table", "--rmax", str(RMAX), "--qmax", str(QMAX)],
                     capture_output=True, text=True, check=True).stdout
f = []
for line in out.strip().splitlines():
    parts = line.split()
    if not parts or not parts[0].lstrip('-').isdigit():
        continue
    f.append([int(x) for x in parts])

def F(x, r):
    return f[x][min(x, r)]

def mex_pos(S):   # mex over positive integers (MISSION recurrence)
    m = 1
    while m in S:
        m += 1
    return m

def mex_nonneg(S):
    m = 0
    while m in S:
        m += 1
    return m

def B(c, x):
    q = c + x
    if q > QMAX:
        raise IndexError
    v = f[q][c] - q
    return v if v >= 0 else None

nfail = 0
steps = 0

# ---- direct derivation check: for every r in 1..RMAX, every q in r..QMAX,
#      the raw recurrence holds, the mex branch is taken with value >= q,
#      {1..q-1} subset S, f(q-1,r) >= q, and the (FR) shift identity. ----
for r in range(1, RMAX + 1):
    for q in range(r, QMAX + 1):
        # raw recurrence
        if r > q:
            val = f[q][q]
        elif f[q-1][r] < q:
            val = f[q-1][r]
        else:
            S = {F(x, r) for x in range(0, q)} | {f[q][b] for b in range(0, r)}
            val = mex_pos(S)
        if val != f[q][r]:
            print(f"FAIL raw recurrence r={r} q={q}: {val} vs {f[q][r]}")
            nfail += 1
            break
        # step 1/2: f(q,r) >= q ; copy branch excluded ; {1..q-1} subset S
        if f[q][r] < q:
            print(f"NOTE f(q,r)<q at r={r} q={q} val={f[q][r]} (stale tail)")
            continue   # after termination; reached-ness is what matters
        steps += 1
        if f[q-1][r] < q:
            print(f"FAIL copy branch taken while f(q,r)>=q: r={r} q={q}")
            nfail += 1
            break
        S = {F(x, r) for x in range(0, q)} | {f[q][b] for b in range(0, r)}
        if not set(range(1, q)) <= S:
            print(f"FAIL {{1..q-1}} not subset S: r={r} q={q}")
            nfail += 1
            break
        # step 3/4: f(q,r) = q + mex_{>=0}(S_q), S_q decomposed as T u V' u V''
        a = q - r
        Sq = {s - q for s in S if s >= q}
        if f[q][r] != q + mex_nonneg(Sq):
            print(f"FAIL shift identity r={r} q={q}")
            nfail += 1
            break
        Vpp = set(); Vp = set()
        for c in range(0, r):
            b = B(c, a + r - c)
            if b is not None: Vpp.add(b)
            b0 = B(c, 0)
            if b0 is not None:
                v = b0 - (r - c) - a
                if v >= 0: Vp.add(v)
        T = set()
        for i in range(1, a + 1):
            # L_{a-i} = f(r+a-i, r) - (r+a-i); must be defined for reached a
            La_i = f[r + a - i][r] - (r + a - i)
            v = La_i - i
            if v >= 0: T.add(v)
        if Sq != (Vpp | Vp | T):
            print(f"FAIL S_q decomposition r={r} q={q}: {sorted(Sq)} vs {sorted(Vpp|Vp|T)}")
            nfail += 1
            break

print(f"# direct derivation check: {steps} reached steps, failures: {nfail}")

# ---- boundary rows: r = 1 (sigma_1 = -1), stale rows, r = 120 anomaly ----
def machine_row(r, verbose=False):
    """Run machine (M) on row r; compare with B_r(a). Return (term_a, ok)."""
    amax = QMAX - r
    maxB = None
    for c in range(0, r):
        for x in range(0, QMAX - c):
            v = B(c, x)
            if v is not None:
                maxB = v if maxB is None else max(maxB, v)
    m_r = 1 + maxB
    H = set()
    for c in range(0, r):
        b0 = B(c, 0)
        if b0 is not None and b0 - (r - c) >= 0:
            H.add(b0 - (r - c))
    for a in range(0, amax + 1):
        Vpp = set()
        for c in range(0, r):
            b = B(c, a + r - c)
            if b is not None: Vpp.add(b)
        k = mex_nonneg(Vpp | H)
        bt = B(r, a)
        if verbose and a < 12:
            print(f"   r={r} a={a} k={k} B_r={bt} H={sorted(H)[:8]}")
        if bt is None or k != bt:
            return (a, False, m_r)
        if k == 0:
            return (a, True, m_r)
        H = {h - 1 for h in H if h >= 1}
        H.add(k - 1)
    return (None, True, m_r)

for r in [1, 2, 3, 4, 5, 6, 7, 120, 121, 6541 if 6541 <= RMAX else 600]:
    if r > RMAX: continue
    ta, ok, m_r = machine_row(r, verbose=(r in (1, 120)))
    print(f"# row r={r}: terminate_a={ta} ok={ok} m_r={m_r} (r+1={r+1})")

# stale-row convention check: termination a should be q0 - r with q0 = N-1
census = {}
with open("census_50000.tsv") as fh:
    for line in fh:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        census[int(p[0])] = dict(cls=p[1], period=int(p[2]), N=int(p[3]), deathq=p[5], dconst=p[6])

bad = 0
for r in range(1, RMAX + 1):
    ce = census[r]
    if ce["cls"] != "stale":
        continue
    ta, ok, _ = machine_row(r)
    q0 = ce["N"] - 1
    if ta != q0 - r or not ok:
        print(f"FAIL stale termination r={r}: term_a={ta}, expected {q0-r}")
        bad += 1
print(f"# stale-row termination convention checked on all stale r<={RMAX}: {bad} failures")

# live rows must never terminate within range
bad = 0
for r in range(1, RMAX + 1):
    ce = census[r]
    if ce["cls"] != "live":
        continue
    ta, ok, _ = machine_row(r)
    if (ta is not None) or not ok:
        print(f"FAIL live row terminated/broken r={r}: term_a={ta} ok={ok}")
        bad += 1
print(f"# live-row non-termination checked on all live r<={RMAX}: {bad} failures")
", "path": "scratch/referee_edges.py"}

{"content": "#!/usr/bin/env python3
"""Boundary / degenerate-case checks + direct check of derivation steps 1-4
of (FR) against the raw MISSION-section-2 recurrence.

Run from working dir root: python3 scratch/referee_edges.py
"""
import subprocess

RMAX = 700
QMAX = 1600

out = subprocess.run(["./solver", "table", "--rmax", str(RMAX), "--qmax", str(QMAX)],
                     capture_output=True, text=True, check=True).stdout
f = []
for line in out.strip().splitlines():
    parts = line.split()
    if not parts or not parts[0].lstrip('-').isdigit():
        continue
    f.append([int(x) for x in parts])

def F(x, r):
    return f[x][min(x, r)]

def mex_pos(S):
    m = 1
    while m in S:
        m += 1
    return m

def mex_nonneg(S):
    m = 0
    while m in S:
        m += 1
    return m

def B(c, x):
    q = c + x
    if q > QMAX:
        raise IndexError
    v = f[q][c] - q
    return v if v >= 0 else None

# ---- (1) direct derivation check on rows r <= 120, q <= 500 ----
nfail = 0
steps = 0
for r in range(1, 121):
    for q in range(r, 501):
        if f[q-1][r] >= q:
            S = {F(x, r) for x in range(0, q)} | {f[q][b] for b in range(0, r)}
            if mex_pos(S) != f[q][r]:
                print(f"FAIL raw recurrence r={r} q={q}")
                nfail += 1
                break
        if f[q][r] < q:
            continue
        steps += 1
        if f[q-1][r] < q:
            print(f"FAIL copy branch taken while f(q,r)>=q: r={r} q={q}")
            nfail += 1
            break
        S = {F(x, r) for x in range(0, q)} | {f[q][b] for b in range(0, r)}
        if not set(range(1, q)) <= S:
            print(f"FAIL {{1..q-1}} not subset S: r={r} q={q}")
            nfail += 1
            break
        a = q - r
        Sq = {s - q for s in S if s >= q}
        if f[q][r] != q + mex_nonneg(Sq):
            print(f"FAIL shift identity r={r} q={q}")
            nfail += 1
            break
        Vpp = set(); Vp = set()
        for c in range(0, r):
            b = B(c, a + r - c)
            if b is not None: Vpp.add(b)
            b0 = B(c, 0)
            if b0 is not None:
                v = b0 - (r - c) - a
                if v >= 0: Vp.add(v)
        T = set()
        for i in range(1, a + 1):
            La_i = f[r + a - i][r] - (r + a - i)
            v = La_i - i
            if v >= 0: T.add(v)
        if Sq != (Vpp | Vp | T):
            print(f"FAIL S_q decomposition r={r} q={q}: {sorted(Sq)} vs {sorted(Vpp|Vp|T)}")
            nfail += 1
            break
print(f"# (1) direct derivation check rows<=120 q<=500: {steps} reached steps, failures: {nfail}")

# ---- (2) machine (M) on a wider sample of rows incl. boundaries ----
def machine_row(r, verbose=False):
    amax = QMAX - r
    maxB = None
    for c in range(0, r):
        for x in range(0, min(QMAX - c, amax + r - c + 1)):
            v = B(c, x)
            if v is not None:
                maxB = v if maxB is None else max(maxB, v)
    m_r = 1 + maxB
    if m_r > r + 1:
        return ("m_r", False, m_r)
    H = set()
    for c in range(0, r):
        b0 = B(c, 0)
        if b0 is not None and b0 - (r - c) >= 0:
            H.add(b0 - (r - c))
    for a in range(0, amax + 1):
        Vpp = set()
        for c in range(0, r):
            b = B(c, a + r - c)
            if b is not None: Vpp.add(b)
        k = mex_nonneg(Vpp | H)
        bt = B(r, a)
        if verbose and a < 12:
            print(f"   r={r} a={a} k={k} B_r={bt} H={sorted(H)[:8]}")
        if bt is None or k != bt:
            return (a, False, m_r)
        if not H <= set(range(m_r)):
            return (a, False, m_r)
        if k == 0:
            return (a, True, m_r)
        H = {h - 1 for h in H if h >= 1}
        H.add(k - 1)
    return (None, True, m_r)

sample = sorted(set([1, 2, 3, 4, 5, 6, 7, 119, 120, 121, 122, 239, 240, 241,
                     360, 361, 600, 601, 654, 655, 656, 699, 700]
                    + list(range(1, 701, 37))))
nfail2 = 0
for r in sample:
    ta, ok, m_r = machine_row(r, verbose=(r in (1, 120)))
    if not ok:
        print(f"FAIL machine r={r}: at a={ta}, m_r={m_r}")
        nfail2 += 1
print(f"# (2) machine (M) on {len(sample)} sampled rows incl. r=1, stale rows, r=120: failures {nfail2}")

# ---- (3) stale/live conventions from solver data, all r <= 700 ----
census = {}
with open("census_50000.tsv") as fh:
    for line in fh:
        if line.startswith("#") or line.startswith("r\t"): continue
        p = line.rstrip("\n").split("\t")
        census[int(p[0])] = dict(cls=p[1], period=int(p[2]), N=int(p[3]))

bad = 0
for r in range(1, RMAX + 1):
    ce = census[r]
    q0 = ce["N"] - 1
    if ce["cls"] == "stale":
        # B_r(q0-r) must be 0 (=f(q0,r)=q0), B_r(a) undefined for a>q0-r,
        # defined for a<q0-r
        if B(r, q0 - r) != 0:
            print(f"FAIL stale: B_r(q0-r) != 0 at r={r}: {B(r, q0-r)}"); bad += 1
        for a in range(q0 - r + 1, min(q0 - r + 30, QMAX - r + 1)):
            if B(r, a) is not None:
                print(f"FAIL stale: B_r defined after termination r={r} a={a}"); bad += 1
        for a in range(0, q0 - r):
            if B(r, a) is None or B(r, a) < 1:
                print(f"FAIL stale: B_r undefined/zero before termination r={r} a={a}"); bad += 1
    else:
        p = ce["period"]; N = ce["N"]
        for a in range(0, QMAX - r - p):
            if B(r, a) is None:
                print(f"FAIL live: B_r undefined r={r} a={a}"); bad += 1
            elif a >= N - r and B(r, a) != B(r, a + p):
                print(f"FAIL live: not {p}-periodic from N r={r} a={a}"); bad += 1
print(f"# (3) stale/live conventions all r<={RMAX}: {bad} failures")

# ---- (4) m_r <= r+1 and B_c(x) <= c+1 everywhere in the grid ----
bad = 0
for c in range(0, RMAX + 1):
    for x in range(0, QMAX - c + 1):
        v = B(c, x)
        if v is not None and v > c + 1:
            print(f"FAIL B_c(x) <= c+1: c={c} x={x} v={v}"); bad += 1
print(f"# (4) bound B_c(x) <= c+1 over full {RMAX}x{QMAX} grid: {bad} failures")
", "path": "scratch/referee_edges.py"}
